<?php
declare(strict_types=1);

final class PostCategories
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function text(array $input,string $key,bool $empty=false):string{$v=$input[$key] ?? null;if(!is_string($v))throw new HttpError(400,'Tên chuyên mục không hợp lệ.');$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);if($v===null||(!$empty&&$v==='')||strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2>100)throw new HttpError(400,'Tên chuyên mục tối đa 100 ký tự.');return $v;}
    private function entries(array $categories,array $posts):array
    {
        $entries=['Cẩm nang'=>['name'=>'Cẩm nang','englishName'=>'Travel guide','version'=>0,'postCount'=>0]];foreach($categories as $row)$entries[$row['name']]=['name'=>$row['name'],'englishName'=>$row['english_name'],'version'=>(int)$row['version'],'postCount'=>0];foreach($posts as $row){$p=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$name=$p['category'] ?? 'Cẩm nang';if($name==='')continue;if(!isset($entries[$name]))$entries[$name]=['name'=>$name,'englishName'=>null,'version'=>0,'postCount'=>0];$entries[$name]['postCount']++;if($entries[$name]['englishName']===null&&trim($p['english']['category'] ?? '')!=='')$entries[$name]['englishName']=$p['english']['category'];}foreach($entries as &$entry)if($entry['englishName']===null)$entry['englishName']=$entry['name']==='Cẩm nang'?'Travel guide':'';unset($entry);uasort($entries,fn($a,$b)=>strnatcasecmp($a['name'],$b['name']));return array_values($entries);
    }
    public function list():array{return $this->entries($this->query('SELECT name,english_name,version FROM jingo_post_categories')->fetchAll(PDO::FETCH_ASSOC),$this->query('SELECT data FROM jingo_posts')->fetchAll(PDO::FETCH_ASSOC));}
    public function act(string $operation,array $input,string $actor):array
    {
        $allowed=match($operation){'CREATE'=>['name'],'TRANSLATE'=>['name','englishName','version'],'RENAME'=>['name','newName','version'],'DELETE'=>['name','version'],default=>throw new HttpError(400,'Thao tác không hợp lệ.')};if(array_diff(array_keys($input),$allowed))throw new HttpError(400,'Dữ liệu chuyên mục không hợp lệ.');$name=self::text($input,'name');$new=$operation==='RENAME'?self::text($input,'newName'):null;$english=$operation==='TRANSLATE'?self::text($input,'englishName',true):null;if($operation!=='CREATE'&&(!is_int($input['version'] ?? null)||$input['version']<0||$input['version']>2147483646))throw new HttpError(400,'Phiên bản chuyên mục không hợp lệ.');if(in_array($operation,['RENAME','DELETE'],true)&&$name==='Cẩm nang')throw new HttpError(400,'Giữ chuyên mục mặc định Cẩm nang.');
        $this->db->beginTransaction();try{
            if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa catalog.');$categories=$this->query('SELECT name,english_name,version FROM jingo_post_categories ORDER BY name FOR UPDATE')->fetchAll(PDO::FETCH_ASSOC);$posts=$this->query('SELECT id,data,version,updated_at FROM jingo_posts ORDER BY id FOR UPDATE')->fetchAll(PDO::FETCH_ASSOC);$entries=$this->entries($categories,$posts);$current=null;foreach($entries as $entry)if($entry['name']===$name)$current=$entry;
            if($operation==='CREATE'){
                if($current){$this->db->commit();return $entries;}foreach($entries as $entry)if(mb_strtolower($entry['name'],'UTF-8')===mb_strtolower($name,'UTF-8'))throw new HttpError(409,'Tên chuyên mục đã tồn tại.');$this->query('INSERT INTO jingo_post_categories(name) VALUES (?)',[$name]);
            }else{
                if(!$current)throw new HttpError(404,'Không tìm thấy chuyên mục.');if($current['version']!==$input['version'])throw new HttpError(409,'Chuyên mục đã thay đổi. Tải lại trước khi lưu.');if($operation==='TRANSLATE'){if($current['version']===0)$this->query('INSERT INTO jingo_post_categories(name,english_name) VALUES (?,?)',[$name,$english]);else $this->query('UPDATE jingo_post_categories SET english_name=?,version=version+1 WHERE name=?',[$english,$name]);}
                else{
                    $target=$operation==='DELETE'?'Cẩm nang':$new;if($target===$name){$this->db->commit();return $entries;}if($operation==='RENAME')foreach($entries as $entry)if($entry['name']!==$name&&mb_strtolower($entry['name'],'UTF-8')===mb_strtolower($target,'UTF-8'))throw new HttpError(409,'Tên chuyên mục đã tồn tại.');$targetEnglish='Travel guide';foreach($entries as $entry)if($entry['name']===$target)$targetEnglish=$entry['englishName'] ?: $target;$this->query('INSERT INTO jingo_post_categories(name) VALUES (?) ON DUPLICATE KEY UPDATE name=name',[$target]);if($operation==='RENAME'){$renameEnglish=null;foreach($categories as $category)if($category['name']===$name)$renameEnglish=$category['english_name'];if($renameEnglish===null)foreach($posts as $postRow){$legacy=json_decode($postRow['data'],true,512,JSON_THROW_ON_ERROR);if(($legacy['category'] ?? '')===$name&&trim($legacy['english']['category'] ?? '')!==''){$renameEnglish=$legacy['english']['category'];break;}}$this->query('UPDATE jingo_post_categories SET english_name=?,version=? WHERE name=?',[$renameEnglish,$current['version']+1,$target]);}
                    foreach($posts as $row){$data=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);if(($data['category'] ?? 'Cẩm nang')!==$name)continue;if((int)$row['version']>=2147483647)throw new HttpError(409,'Bài viết đã đạt giới hạn phiên bản.');$data['category']=$target;if(isset($data['english'])){if($operation==='DELETE')$data['english']['category']=$targetEnglish;if(($data['english']['status'] ?? '')==='NEEDS_REVIEW')$data['english']['status']='PUBLISHED';}$this->query("INSERT INTO jingo_post_revisions(post_id,version,data,saved_by,reason,created_at) SELECT id,version,data,'legacy','BASELINE',updated_at FROM jingo_posts WHERE id=? AND NOT EXISTS(SELECT 1 FROM jingo_post_revisions WHERE post_id=? AND version=?)",[$row['id'],$row['id'],$row['version']]);$this->query('UPDATE jingo_posts SET data=?,version=version+1,updated_at=UTC_TIMESTAMP(6) WHERE id=?',[json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$row['id']]);$this->query('INSERT INTO jingo_post_revisions(post_id,version,data,saved_by,reason,created_at) SELECT id,version,data,?,?,updated_at FROM jingo_posts WHERE id=?',[$actor,'CATEGORY_'.$operation,$row['id']]);}
                    $this->query('DELETE FROM jingo_post_categories WHERE name=?',[$name]);
                }
            }
            $this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'post-category.'.strtolower($operation),hash('sha256',$name)]);$this->db->commit();return $this->list();
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&($e->errorInfo[1] ?? null)===1062)throw new HttpError(409,'Chuyên mục đã thay đổi hoặc trùng tên.');throw $e;}
    }
}
